CREATE OR REPLACE FUNCTION public.aurora_ingest_exercise_series_editorial(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare v jsonb := coalesce(p_payload,'{}'::jsonb); v_content jsonb := coalesce(v->'content_json','{}'::jsonb); v_profile jsonb := coalesce(v->'profile','{}'::jsonb); v_sections jsonb := case when jsonb_typeof(v_content->'sections')='array' then v_content->'sections' else '[]'::jsonb end; v_exercises jsonb := '[]'::jsonb; v_job uuid; v_doc bigint; v_item uuid; v_ingest text := nullif(trim(v->>'ingest_id'),''); v_title text := nullif(trim(v->>'title'),''); v_subject text := nullif(trim(v->>'subject'),''); v_level text := nullif(trim(v->>'level'),''); v_class text := nullif(trim(v->>'class_name'),''); v_matiere text := nullif(trim(coalesce(v->>'matiere',v->>'subject')),''); v_idx int := 0; v_pos int := 0; v_ex jsonb; v_item_ids jsonb := '[]'::jsonb; v_canonical_sections jsonb := '[]'::jsonb; v_section jsonb; v_section_exs jsonb; v_num int; v_statement text; v_correction text; v_presentation jsonb := coalesce(v->'presentation',jsonb_build_object('type','exercise_series','sequence',jsonb_build_array('title','toc','exercise','correction'),'compact_text',true,'formula_priority',true,'detailed_corrections',true)); v_metadata jsonb; begin if auth.uid() is null then raise exception 'Authentification requise'; end if; if not public.is_admin() then raise exception 'Accès administrateur requis'; end if; if lower(coalesce(v_profile->>'kind','')) <> 'exercices' or coalesce(v_profile->>'version','') <> 'exercise-sheet-v2' then raise exception 'Profil exercice invalide : exercise-sheet-v2 obligatoire'; end if; if v_title is null then raise exception 'Titre de série obligatoire'; end if; if jsonb_typeof(v_content) <> 'object' then raise exception 'content_json doit être un objet'; end if; if v_ingest is null or length(v_ingest)>120 then raise exception 'ingest_id invalide'; end if; for v_section in select value from jsonb_array_elements(v_sections) loop v_section_exs := case when jsonb_typeof(v_section->'exercises')='array' then v_section->'exercises' else '[]'::jsonb end; for v_ex in select value from jsonb_array_elements(v_section_exs) loop if jsonb_typeof(v_ex) <> 'object' then continue; end if; v_num := coalesce(nullif(v_ex->>'exercise_number','')::int, v_idx+1); v_idx := v_idx + 1; v_exercises := v_exercises || jsonb_build_array(jsonb_build_object('exercise_number',v_num,'title',coalesce(nullif(trim(v_ex->>'title'),''),format('Exercice %s',v_idx)),'statement',coalesce(v_ex->>'statement',v_ex->>'question',v_ex->>'enonce',v_ex->>'content',''),'correction',coalesce(v_ex->>'correction',v_ex->>'solution',v_ex->>'details',''),'difficulte',v_ex->>'difficulte','competences',coalesce(v_ex->'competences','[]'::jsonb),'metadata',coalesce(v_ex->'metadata','{}'::jsonb),'statement_graphs',coalesce(v_ex->'statement_graphs','[]'::jsonb),'correction_graphs',coalesce(v_ex->'correction_graphs','[]'::jsonb))); end loop; end loop; if jsonb_array_length(v_exercises)=0 and jsonb_typeof(v_content->'exercises')='array' then v_exercises := v_content->'exercises'; end if; if jsonb_array_length(v_exercises)<2 then raise exception 'EXERCISE_SERIES_BLOCKED: une série doit contenir au moins 2 exercices structurés'; end if; insert into public.aurore_exercice_jobs(created_by,title,subject,level,class_name,filiere,matiere,source_type,source_prompt,source_content,status,current_stage,progress_percent,metadata,preserve_first_page,preserve_last_page,presentation) values(auth.uid(),v_title,v_subject,v_level,v_class,nullif(trim(v->>'filiere'),''),v_matiere,'ia',v->>'prompt',v_content,'waiting_validation','exercise_validation',30,coalesce(v->'metadata','{}'::jsonb) || jsonb_build_object('origin','gpt_editorial_ingest','connector_mode',true,'exercise_pipeline',true,'aurore_profile',v_profile,'ingest_id',v_ingest,'content_job_id',nullif(v->>'content_job_id','')::bigint,'manual_publication_only',true,'manual_pdf_launch_required',true,'auto_pdf_launch',false,'presentation',v_presentation),true,true,v_presentation) returning id into v_job; for v_ex in select value from jsonb_array_elements(v_exercises) loop v_num := coalesce(nullif(v_ex->>'exercise_number','')::int, v_pos+1); v_statement := trim(coalesce(v_ex->>'statement',v_ex->>'question',v_ex->>'enonce',v_ex->>'content','')); v_correction := trim(coalesce(v_ex->>'correction',v_ex->>'solution',v_ex->>'details','')); v_pos := v_pos + 1; insert into public.aurore_exercice_items(job_id,position,titre,enonce,correction,reponse_attendue,difficulte,competences,metadata,exercice_number,section_title,presentation_order) values(v_job,v_pos,coalesce(nullif(trim(v_ex->>'title'),''),format('Exercice %s',v_num)),v_statement,v_correction,nullif(trim(v_ex->>'reponse_attendue'),''),nullif(trim(v_ex->>'difficulte'),''),coalesce(v_ex->'competences','[]'::jsonb),coalesce(v_ex->'metadata','{}'::jsonb) || jsonb_build_object('statement_graphs',coalesce(v_ex->'statement_graphs','[]'::jsonb),'correction_graphs',coalesce(v_ex->'correction_graphs','[]'::jsonb)),v_num,nullif(trim(v_ex->>'section_title'),''),v_pos) returning id into v_item; v_item_ids := v_item_ids || jsonb_build_array(v_item); end loop; v_pos := 0; for v_idx in 0..jsonb_array_length(v_exercises)-1 loop v_ex := v_exercises->v_idx; v_pos := v_pos + 1; v_item := (v_item_ids->v_idx #>> '{}')::uuid; insert into public.aurore_exercice_blocks(job_id,item_id,block_type,position,title,content,metadata) values(v_job,v_item,'exercise',v_pos,coalesce(v_ex->>'title',format('Exercice %s',v_idx+1)),jsonb_build_object('source','item'),jsonb_build_object()); v_pos := v_pos + 1; insert into public.aurore_exercice_blocks(job_id,item_id,block_type,position,title,content,metadata) values(v_job,v_item,'correction',v_pos,format('Corrigé — Exercice %s',v_idx+1),jsonb_build_object('source','item'),jsonb_build_object()); end loop; for v_idx in 0..jsonb_array_length(v_exercises)-1 loop v_ex := v_exercises->v_idx; v_canonical_sections := v_canonical_sections || jsonb_build_array(jsonb_build_object('title',coalesce(v_ex->>'title',format('Exercice %s',v_idx+1)),'content',jsonb_build_array(coalesce(v_ex->>'statement','')),'exercises',jsonb_build_array(jsonb_build_object('title',coalesce(v_ex->>'title',format('Exercice %s',v_idx+1)),'statement',coalesce(v_ex->>'statement',''),'correction',coalesce(v_ex->>'correction',''),'difficulte',v_ex->>'difficulte','competences',coalesce(v_ex->'competences','[]'::jsonb),'statement_graphs',coalesce(v_ex->'statement_graphs','[]'::jsonb),'correction_graphs',coalesce(v_ex->'correction_graphs','[]'::jsonb))),'corrections',jsonb_build_array(jsonb_build_object('exercise_number',v_idx+1,'exercise_id',format('exercise-%s',v_idx+1),'content',coalesce(v_ex->>'correction',''))),'graphs',jsonb_build_array())); end loop; v_content := jsonb_set(v_content,'{title}',to_jsonb(v_title),true); v_content := jsonb_set(v_content,'{document_type}',to_jsonb('exercices'::text),true); v_content := jsonb_set(v_content,'{sections}',v_canonical_sections,true); v_content := jsonb_set(v_content,'{presentation}',v_presentation,true); v_metadata := coalesce(v->'metadata','{}'::jsonb) || jsonb_build_object('origin','gpt_editorial_ingest','connector_mode',true,'pipeline','ChatGPT editor -> native exercise pipeline -> Aurore renderer','exercise_job_id',v_job,'exercise_pipeline',true,'exercise_presentation',v_presentation,'aurore_profile',v_profile,'content_job_id',nullif(v->>'content_job_id','')::bigint,'ingest_id',v_ingest,'human_review_required',true,'manual_publication_only',true,'lualatex_requested',false,'lualatex_status','not_requested','production_status','pending','pending_admin_surface','documents_en_attente','manual_pdf_launch_required',true,'auto_pdf_launch',false,'qa',jsonb_build_object('exercise_count',jsonb_array_length(v_exercises),'block_count',jsonb_array_length(v_exercises)*2)); insert into public.aurora_generated_documents(job_id,created_by,title,subject,level,class_name,document_type,source_format,source_content,content_json,pdf_path,pdf_url,version,status,validation_notes,published_document_id,metadata,matiere,ingest_id) values(nullif(v->>'content_job_id','')::bigint,auth.uid(),v_title,v_subject,v_level,v_class,'exercices','structured',null,v_content,null,null,1,'review','Série d’exercices éditée par D. Contrôle humain requis avant publication.',null,v_metadata,v_matiere,v_ingest) returning id into v_doc; update public.aurore_exercice_jobs set generated_document_id=v_doc,status='waiting_validation',current_stage='exercise_validation',progress_percent=30,updated_at=now() where id=v_job; insert into public.aurore_exercice_job_events(job_id,stage,status,progress_percent,message,metadata) values(v_job,'exercise_validation','progress',30,'Série d’exercices reçue depuis D et insérée dans le pipeline natif.',jsonb_build_object('generated_document_id',v_doc,'content_job_id',nullif(v->>'content_job_id','')::bigint)); return jsonb_build_object('ok',true,'duplicate',false,'exercise_job_id',v_job,'generated_document_id',v_doc,'exercise_count',jsonb_array_length(v_exercises),'block_count',jsonb_array_length(v_exercises)*2); end; $function$

revoke all on function public.aurora_ingest_exercise_series_editorial(jsonb) from public;
grant execute on function public.aurora_ingest_exercise_series_editorial(jsonb) to authenticated;
